let phone = $input.item.json['Coordinator Phone'] || '';

// Strip everything except digits and +
phone = phone.replace(/[^0-9+]/g, '');

// If it's 10 digits (Indian local), add +91
if (/^[6-9]\d{9}$/.test(phone)) {
  phone = '+91' + phone;
}

// If it starts with 91 but no +, add +
if (/^91[6-9]\d{9}$/.test(phone)) {
  phone = '+' + phone;
}

// If it's still not a valid +91 number, skip it
if (!/^\+91[6-9]\d{9}$/.test(phone)) {
  return [];
}

$input.item.json['Coordinator Phone'] = phone;
return {json: $input.item.json};
